/* generat de tools/i18n25/hub-i18n.mjs din data/hub-i18n/apps/ru.json — nu edita de mână */
__hubApps("ru",{"FreeDetect":{"line":"Хотите проверить, похож ли текст на написанный или скопированный ИИ? 42 внешних инструмента и генератор цитат в одном месте. Само приложение ничего не определяет.","detail":"Панель из 42 внешних инструментов для обнаружения ИИ и плагиата и генератор цитат (проверяет ISBN). Сама ничего не обнаруживает; помогает проверять ссылки на источники.","tags":["каталог","цитаты"]},"Arhiva-fara-frontiere":{"line":"Просматривайте коллекции Internet Archive без аккаунта: поиск, страницы материалов, предпросмотр и избранное. Неофициальное приложение; archive.org видит ваш IP-адрес и запросы.","detail":"Неофициальный браузер по коллекциям Internet Archive (поиск, страницы материалов, предпросмотр, избранное и недавние запросы сохраняются локально), без аккаунта. Не ищет в Wayback Machine; archive.org получает ваш IP и поисковые запросы.","tags":["веб-архивы","источники"]},"AcademiSearch":{"line":"Один поиск — научные статьи из десятков открытых источников. Список можно сохранить для цитирования. Нужен интернет; запросы уходят этим сервисам.","detail":"Академический метапоиск по 11 открытым API (OpenAlex, Crossref, arXiv и др.) плюс ссылки на порталы; экспорт в BibTeX/RIS/CSV. Требуется интернет; ваши запросы уходят этим сервисам.","tags":["литература","источники"]},"Surveyor":{"line":"Какие ссылки есть на вашем сайте и какие из них не работают? Перечисляет их вместе с якорями и перенаправлениями. Внешние ссылки нельзя проверить надёжно. Только для ваших собственных сайтов.","detail":"Составляет перечень ссылок сайта (статический HTML, интерфейс на английском), включая якоря и перенаправления. Внешние ссылки нельзя проверить из браузера (CORS); приложение отправляет запросы; проверяйте только собственные сайты.","tags":["битые ссылки","аудит"]},"Trade-Free-Link-Guardian":{"line":"Для вашего сайта на WordPress: находит битые ссылки и исправляет их без внешних сервисов. Меняет реальное содержимое, поэтому сначала сделайте резервную копию. На настоящем WordPress не проверялось.","detail":"Плагин WordPress, который проверяет ссылки и детерминированно исправляет неработающие, без внешних сервисов. Он изменяет реальное содержимое: сделайте резервную копию. Не тестировался на реальном WordPress.","tags":["WordPress","GPL v2"]},"OUTPOST":{"line":"Следите за своими сайтами и смотрите, отвечают ли они. Работает, только пока вкладка открыта. Страница с ошибкой тоже считается ответом. Интерфейс на английском.","detail":"Монитор доступности в браузере: проверяет, отвечают ли ваши сайты (не читает код состояния HTTP; 404/500 считаются ответом). Работает только пока вкладка открыта. Интерфейс на английском.","tags":["мониторинг"]},"ScryVeil":{"line":"Проверьте безопасность домена и получите текстовый отчёт, который можно сохранить. Некоторые проверки могут быть неполными или требовать ключ. Обращается к сторонним сервисам; только для ваших доменов.","detail":"Диагностика безопасности домена (DNS, RDAP, сертификаты) с экспортируемым текстовым отчётом; проверки заголовков и репутации часто блокируются или требуют ключ. Обращается к сторонним службам; только для доменов, которыми вы владеете.","tags":["OSINT","безопасность"]},"Vitrina":{"line":"Вставьте публичную публикацию Facebook на свой сайт без аккаунта и скопируйте готовый код. Неофициально; Meta видит ваш IP, показ не гарантирован.","detail":"Встраивает публичные страницы и публикации Facebook через плагины Meta, неофициально; копирует код для встраивания. «Без аккаунта» не значит «без отслеживания»: Meta видит ваш IP; отображение не гарантируется.","tags":["мониторинг лент"]},"Threads-fara-cont":{"line":"Читайте публичные публикации Threads без аккаунта и сохраняйте их как текст. Неофициально; Meta видит ваш IP, иногда нужен посредник.","detail":"Показывает публичные публикации Threads через встраивание Meta, без аккаунта; по желанию локальное сохранение, экспорт в .txt. Meta видит ваш IP; может потребоваться прокси CORS. Неофициально.","tags":["мониторинг лент"]},"X-fara-cont":{"line":"Открывайте публичные профили и публикации в X без аккаунта несколькими способами: прямая ссылка, архив, поиск или Nitter. Содержимое не читает; отправляет ссылку в archive.org.","detail":"Создаёт пути доступа без аккаунта к публичным профилям и публикациям X: прямая ссылка, архив Wayback, поиск, Nitter. Содержимое не читает; отправляет имя пользователя или ссылку в archive.org.","tags":["мониторинг лент"]},"Arhiva-LinkedIn":{"line":"Храните в одном месте заметки о публикациях LinkedIn, которые вы сами вставили, и экспортируйте их как текст. Галерея использует официальное встраивание, поэтому обращается к LinkedIn. Неофициально.","detail":"Архив заметок к вручную вставленным публикациям LinkedIn (импорт CSV, экспорт в Markdown) + галерея через официальное встраивание LinkedIn (обращается к LinkedIn). Неофициально.","tags":["архивирование"]},"Cadraj":{"line":"Собирайте клипы TikTok вручную, группируя по автору, и смотрите их в официальном плеере. Можно отмечать уже просмотренные.","detail":"Ручная подборка клипов TikTok по авторам, воспроизводимых через официальный плеер; отметка «просмотрено».","tags":["мониторинг лент"]},"FASCICUL":{"line":"Превращает телефоны в комнате в общую доску на видеопроекторе: рисунки, заметки, изображения, лазерная указка и живая камера. Проверено на компьютере; на реальных телефонах пока не подтверждено.","detail":"Телефоны ↔ видеопроектор: общая доска с рисованием, заметками, изображениями, лазерной указкой и живой камерой, в одном файле. Прямое соединение WebRTC в локальной сети, без стороннего сервера; необязательное реле на телефоне-точке доступа (Android/Termux). Протестировано в Chromium; на реальных телефонах пока не проверено.","tags":["совместная работа"]},"INDICATIV":{"line":"Готовьтесь к радиолюбительскому экзамену ANCOM без интернета: 723 вопроса с интервальным повторением. Неофициально; банк вопросов проверен лишь частично.","detail":"Офлайн-тренажёр для экзамена ANCOM по любительской радиосвязи, неофициальный (723 вопроса, интервальное повторение, поиск по банку вопросов). Не материал ANCOM; банк вопросов проверен лишь частично.","tags":["экзамен","радио"]},"ETER":{"line":"Изучайте любительскую радиосвязь в энциклопедии: азбука Морзе, тренажёр, калькуляторы антенн и поиск по всему содержимому.","detail":"Энциклопедия любительской радиосвязи: азбука Морзе, тренажёр Коха, калькуляторы антенн, глобальный поиск.","tags":["радио","энциклопедия"]},"ATINGERE":{"line":"Превращает книгу в шрифт Брайля с вибрацией на сенсорном экране для слепоглухих или в аудиокнигу для слепых. С читателями Брайля не проверялось; есть ограничения.","detail":"Преобразует книги в тактильный шрифт Брайля или аудиокниги. Не проверено с носителями шрифта Брайля; ограничения см. в README.","tags":["доступность"]},"Clopotel":{"line":"Укладывайтесь по времени на конференции или семинаре: сценический таймер с вашей программой и сигнал о приближении конца. На румынском и английском.","detail":"Таймер для сцены с повесткой выступающих (импорт текста/CSV) и предупреждающим сигналом, RO/EN.","tags":["мероприятия","MIT"]},"Monstrarium":{"line":"Спланируйте мастерскую по созданию монстров из вторсырья: приложение считает материалы и занятия, предлагает 50 монстров со звуком, 3D и обучающей игрой.","detail":"Планировщик мастерской монстров из вторсырья: сам рассчитывает материалы, расписание по сериям, 50 оригинальных монстров со звуками, 3D и обучающая игра.","tags":["мастерская","MIT"]},"TranslateHub":{"line":"Выбирайте среди 22 инструментов перевода или переводите с ИИ по собственному ключу. Текст, переведённый ИИ, уходит в сервис Anthropic.","detail":"Каталог из 22 инструментов перевода плюс ИИ-переводчик с вашим собственным ключом. Текст для ИИ отправляется на api.anthropic.com.","tags":["перевод","ИИ"]},"DataWeave":{"line":"Откройте таблицу и разберитесь в ней: статистика, графики, сводные таблицы и корреляции. Ваши данные остаются на устройстве.","detail":"Просмотр CSV/TSV/JSON в одном файле: таблица, статистика, графики, сводная таблица и корреляции; ваши данные остаются на вашем устройстве.","tags":["данные"]},"MarkdownAtelier":{"line":"Пишите документы в Markdown и сразу смотрите, как они выглядят, с простыми формулами; на 7 языках, без интернета. Тексты остаются в браузере; сохраняйте резервную копию.","detail":"Офлайн-редактор Markdown с предпросмотром, GFM, подмножеством LaTeX (MathML), 7 языками, поиском и резервной копией в .json. Документы остаются в браузере.","tags":["письмо"]},"RegexLab":{"line":"Пробуйте регулярное выражение и сразу видите, что оно находит; пошаговые объяснения, тесты и предупреждение, если оно может зависнуть.","detail":"Проверка регулярных выражений JavaScript с пояснениями, тестами и предупреждением о ReDoS.","tags":["разработка"]},"SEOptimum":{"line":"Проверьте, насколько веб-страница готова к поисковым системам. 20 инструментов, включая анализ страницы и предпросмотр её вида в результатах поиска.","detail":"20 SEO-инструментов в браузере: анализ страницы, предпросмотр выдачи.","tags":["веб"]},"SEVA":{"line":"Узнайте о сне, суточном ритме организма, дыхании и питании в энциклопедии, которую можно прослушать. Только информация; не медицинская рекомендация.","detail":"Энциклопедия благополучия: сон, циркадный ритм, дыхание, питание; прослушивание с озвучиванием. Информационный материал; не медицинская рекомендация.","tags":["здоровье"]},"PULS":{"line":"Что делать, пока едет скорая? Румынское руководство по первой помощи с метрономом для СЛР и необязательной экстренной карточкой. Клинически не проверено; звоните 112.","detail":"Руководство по первой помощи на румынском языке (СЛР с метрономом, жгут), с поиском и необязательной карточкой экстренной помощи. Содержание не прошло клиническую проверку специалиста; не заменяет авторизованный курс. В экстренной ситуации звоните по номеру 112.","tags":["здоровье","экстренные случаи"]},"VATRA":{"line":"Что делать, если в природе закончилась вода, огонь или нет укрытия? Энциклопедия выживания без интернета с поиском и заметками. Только для обучения; в экстренной ситуации звоните 112.","detail":"Офлайн-энциклопедия выживания (вода, огонь, укрытие, навигация) с поиском и локально сохраняемыми заметками. Учебный материал, не заменяет курс первой помощи; в экстренной ситуации звоните по номеру 112.","tags":["полевые условия"]},"Eclipsa-2027":{"line":"Посмотрите на карте без интернета, где и как долго продлится полное солнечное затмение 2 августа 2027 года, с городами и поиском места. Значения приблизительные; не смотрите на Солнце без фильтра.","detail":"Офлайн-карта полного солнечного затмения 2 августа 2027 года с продолжительностью, охватом по городам и поиском места. Ориентировочные значения; не смотрите на Солнце без сертифицированных фильтров.","tags":["астрономия"]},"orarium":{"line":"Который час сейчас на Марсе, на Луне или на астероиде? Живое местное время на 45 небесных телах. Приближённая модель, интернет не нужен; не для навигации.","detail":"Время на каждом мире: местное время в реальном времени на 45 телах (Луна, Марс, планеты, спутники, астероиды), скорость хода часов относительно Земли, расстояние и время прохождения сигнала туда и обратно, конвертер часовых поясов и карты колонизации. Ориентировочная модель, офлайн; не для навигации. Включает полночь и полдень на каждом теле, окна передачи Земля—тело и ссылку на TerRa.","tags":["астрономия","время"]},"TerRa":{"line":"3D-глобус и карта, показывающие день и ночь на Земле, Луне и планетах. Положения спутников могут отставать примерно на 3 месяца, пока вы не обновите их онлайн.","detail":"3D-глобус и карта: терминатор, Луна, планеты. Спутники используют устаревший снимок (около 3 месяцев) в офлайне; для актуальных положений обновите онлайн. Уникальная ссылка для каждого вида; небо с любого из 45 тел ORARIUM, со связью в обе стороны.","tags":["астрономия"]},"Horizons.BeyondLimits":{"line":"Путешествуйте по истории Вселенной от Большого взрыва до конца через 91 веху. Будущее — научная гипотеза, а не точный прогноз.","detail":"Карта временной шкалы от Большого взрыва до конца Вселенной: 91 событие, экспорт в Markdown; будущее носит спекулятивный характер, это не проверенный прогноз.","tags":["космология"]},"Hyper4D":{"line":"Посмотрите, как выглядят четырёхмерные фигуры: вращайте их на экране и рассматривайте с разных сторон. Изображения можно сохранить.","detail":"4D-геометрия в SVG: 3D-сечения 4D-тел и политопов с проекциями 4D→3D→2D, вращаемыми в реальном времени, экспорт в SVG.","tags":["математика"]},"ExploratoriiEco":{"line":"Полевой справочник для любителей природы: от классификации живых существ и следов до биомов Румынии, дневник наблюдений, этика и экстренные случаи.","detail":"Полевой справочник натуралиста в 20 разделах: классификация жизни, признаки и следы, биомы Румынии, калькуляторы, журнал наблюдений, этика, экстренные ситуации и глоссарий.","tags":["природа"]},"FieldObserver":{"line":"Записывайте полевые наблюдения; показания датчиков телефона добавляются автоматически. Вы ведёте архив своих выходов.","detail":"Журнал полевых наблюдений с использованием датчиков телефона; архив, экспорт в JSON/CSV.","tags":["полевые условия"]},"VietAR":{"line":"Сфотографируйте или запишите растение либо существо и получите представление о нём среди 519 видов из Румынии. Может ошибаться; ничего не ешьте на этом основании.","detail":"Ориентировочное определение 519 румынских видов по изображению/звуку; может ошибаться, не ешьте растения и грибы на основании результата. Модели загружаются от третьих сторон; не полностью офлайн.","tags":["биоразнообразие"]},"VOIAJOR":{"line":"Следите за траекториями «Вояджера-1» и «Вояджера-2» с 1977 года и на миллиард лет вперёд, в любом масштабе — от планет до Млечного Пути. Ориентировочная модель, не для навигации.","detail":"Симуляция траекторий Voyager 1 и 2 (с 1977 года и более миллиарда лет): баллистические дуги между реальными пролётами, экстраполяция с учётом солнечной гравитации и локальной галактической динамики, гелиосфера, облако Оорта и 19 ближайших звёзд с собственным движением.","tags":["Вояджер","симуляция"]},"Nemurirea":{"line":"Узнайте, как стареет организм и что наука говорит о биологических часах и долголетии, затем проверьте себя в тесте. Не медицинская рекомендация.","detail":"Интерактивное эссе о биологических часах и науке о долголетии с итоговой викториной. Информационная цель, не медицинская рекомендация.","tags":["биология"]},"IncredibleCosmos":{"line":"Расставляйте планеты и звёзды так, чтобы их гравитация направила комету к цели. 108 уровней, три сложности и до трёх звёзд за уровень.","detail":"Головоломка о гравитации: расставьте планеты и звёзды так, чтобы их притяжение направило комету к цели; 108 уровней в 12 категориях, три уровня сложности, оценка от 1 до 3 звёзд, с поиском.","tags":["игра","физика"]},"Cupa-Mondiala-2026":{"line":"Играйте на чемпионате мира 2026 и следите за ходом воображаемого турнира. Результаты случайны, это не прогноз; неофициально.","detail":"Вымышленный неофициальный симулятор чемпионата мира 2026: случайные результаты, не прогнозы; не связан с FIFA.","tags":["симуляция","неофициально"]},"AGORA":{"line":"Как появился евро и что он значит для Румынии? 59 глав от Маастрихта до ЕЦБ и советы путешественникам. Неофициально.","detail":"Информационный атлас еврозоны в 59 разделах: от Маастрихта и ЕЦБ до Румынии и евро, плюс путеводитель для путешественника. Неофициальный, без юридической силы.","tags":["экономика","ЕС"]},"URME":{"line":"Подготовьтесь к походу по тропе Колць–Алуниш в Бузэу: растения, янтарь, окаменелости, время восхода и заката, снаряжение. Карта не для навигации.","detail":"Информационный неофициальный туристический путеводитель по Колци—Алуниш (растения, янтарь, окаменелости) с восходом/закатом и списком снаряжения. Схематичная карта, не для навигации; вывоз из охраняемой территории запрещён.","tags":["природа","Бузэу"]},"Belot-fara-frontiere":{"line":"Узнайте о белоте и родственных играх в других странах, затем сыграйте за столом: вы и партнёр-ИИ против двух соперников-ИИ. Есть бланк для записи очков.","detail":"Атлас семейства игр белот/бела/клавирьяс/яс и игра на 4 игроков (вы и ИИ-партнёр против двух ИИ-соперников); приоритет — румынский белот; лист для подсчёта очков.","tags":["карты","ИИ"]},"Scopone-fara-frontiere":{"line":"Узнайте, как возникла скопоне, каковы её правила и как они меняются от региона к региону, затем сыграйте против компьютера, который умеет давать подсказки.","detail":"Атлас скопоне (15 листов: происхождение, правила, региональные различия) и игра против локального ИИ (эвристика / Монте-Карло), с подсказками; итальянские или французские масти.","tags":["карты","ИИ"]},"Solitaire-fara-frontiere":{"line":"Просматривайте и играйте в пасьянсы вроде Klondike, FreeCell или Spider. Если застряли — попросите подсказку или позвольте компьютеру решить.","detail":"Атлас пасьянсов (Клондайк, FreeCell, Паук и другие) на общем движке; «Подсказка» от решателя с ограничением по узлам/времени и необязательное автоматическое решение.","tags":["карты"]},"Sudoku-fara-frontiere":{"line":"136 видов судоку — от классического до killer и 3D; просматривайте и играйте. Помогает пошаговыми объяснениями и решает ваши собственные головоломки.","detail":"Атлас из 136 вариантов судоку (классическое, киллер, jigsaw, греко-латинское, 3D и многие другие) с генератором задач с единственным решением, пошаговым объяснением решения, 7 игровыми режимами и решателем.","tags":["головоломки"]},"Domino-fara-frontiere":{"line":"Узнайте историю и правила домино, затем сыграйте за столом против одного–трёх соперников под управлением компьютера. Ход можно отменить.","detail":"Атлас домино (происхождение, правила, приближения) и игровой стол против 1–3 ИИ-игроков, с тремя уровнями; отмена хода.","tags":["домино","ИИ"]},"Mahjong-fara-frontiere":{"line":"Познакомьтесь с 8 видами маджонга; играйте в пасьянс или в игру вчетвером с тремя простыми соперниками, которыми управляет компьютер. Работает без интернета.","detail":"Атлас из 8 вариантов маджонга, пасьянс и маджонг на 4 игроков (риичи, гонконгский, сычуаньский) против 3 простых эвристических ИИ. Офлайн.","tags":["маджонг","ИИ"]},"Go-fara-frontiere":{"line":"Узнайте, откуда пришла игра го и как в неё играть, затем попробуйте силы против компьютера, который умеет подсказывать. Никакие данные через интернет не отправляются.","detail":"Атлас го (18 листов: происхождение, правила, приближения) и игра против локального ИИ (Монте-Карло, не LLM), с SGF и подсказками; без сетевых запросов.","tags":["го","ИИ"]},"Zaruri-fara-frontiere":{"line":"26 игр в кости, о которых можно прочитать, 12 из них — против компьютера; плюс симулятор бросков с вероятностями. Без денег; без интернета.","detail":"Атлас из 26 игр в кости; 12 из них можно играть против обучающего ИИ (не LLM), плюс симулятор NdM с точными вероятностями. Не азартная игра; офлайн.","tags":["кости"]},"Sah-fara-frontiere":{"line":"Более 700 разновидностей шахмат и небольшой словарь терминов; в большинство можно играть против компьютера. Работает без интернета.","detail":"706 записей о шахматных вариантах (лишь для части — проверенный источник; некоторые синтетические) и 299 терминов лексикона. Офлайн, с локальным движком для многих вариантов.","tags":["шахматы"]},"Dame-fara-frontiere":{"line":"Играйте в 25 вариантов шашек против компьютера и сохраняйте партию. Правила 16 из них лишь приблизительны и помечены знаком ⚠.","detail":"25 вариантов шашек, в которые можно играть против обучающего ИИ, с экспортом партий; у 16 правила приблизительные (помечены ⚠).","tags":["шашки"]},"Table-fara-frontiere":{"line":"Нарды, тавли, наре и румынские разновидности таблы; читайте и играйте: 17 вариантов против компьютера, с клавиатуры или мышью.","detail":"Играбельный атлас семейства нард: нарды, Тавли, Тавла, Нарде, Гул Бара и румынские варианты; 17 вариантов против обучающего ИИ; игра с клавиатуры.","tags":["нарды"]},"Remi-fara-frontiere":{"line":"Познакомьтесь с семейством рамми и играйте против компьютера в 19 вариантов со статистикой. 8 языков; крупные, хорошо видимые фишки или карты.","detail":"Атлас семейства игр рамми: 19 вариантов, в которые можно играть против локального ИИ, со статистикой; интерфейс на 8 языках, с крупными фишками и картами.","tags":["рамми"]},"Carti-de-joc-fara-frontiere":{"line":"От пасьянса и «Дурака» до покера: 17 карточных игр с объяснёнными правилами, в 8 из них можно сразу играть.","detail":"Интерактивный атлас карточных игр, от пасьянса и «Старой девы» до покера: 17 игр с листами правил, 8 из них играбельны.","tags":["карты"]},"Undava":{"line":"Готовьте викторину или играйте в неё с друзьями на одном телефоне или компьютере и переигрывайте вопросы, на которые ответили неверно. Похоже на Kahoot, но без подключения.","detail":"Викторина в стиле Kahoot (не аффилирована) в одном файле: в одиночку или по очереди на одном устройстве, с повтором ошибок. Игра в реальном времени есть только в серверной версии.","tags":["викторина","обучение"]},"AI-Liber":{"line":"Общайтесь с несколькими ИИ-ассистентами в одном месте, некоторые работают на вашем компьютере. Сообщения уходят выбранному вами провайдеру; ИИ может ошибаться.","detail":"Чат с несколькими ИИ-провайдерами, включая локальные (Ollama, WebLLM). Сообщения уходят выбранному вами провайдеру; ответы ИИ могут быть неверными.","tags":["ИИ"]},"LocalMind":{"line":"Общайтесь с небольшим ИИ-ассистентом, который работает прямо в вашем браузере. Модели скачиваются из интернета один раз; может ошибаться.","detail":"Чат с небольшими моделями (Qwen3, LFM2), запускаемыми локально в браузере (WebGPU). Модели загружаются с Hugging Face; может ошибаться. Требуется локальный сервер или публичная страница.","tags":["локальный ИИ"]},"PromptVault":{"line":"Более 500 готовых промптов для ИИ-ассистентов; выбирайте и отмечайте избранные. Не сохраняет ваши собственные тексты.","detail":"Библиотека из более чем 500 промптов с избранным, не менеджер для ваших собственных промптов.","tags":["промпты"]},"ARENA":{"line":"Заставьте две модели ИИ отвечать вслепую и голосуйте за лучшую; рейтинг хранится на вашем компьютере. Нужны ваши собственные ключи.","detail":"Слепые дуэли между ИИ-моделями с локальным рейтингом Эло (экспорт в CSV). Требуются ваши собственные ключи API или локальные серверы; демонстрационные модели имитируются.","tags":["оценка ИИ"]},"Nexus-fara-frontiere":{"line":"Общайтесь с ИИ-ассистентами нескольких провайдеров; разговор с поиском и сохранением. Нужны интернет и ваши собственные ключи, которые хранятся без шифрования.","detail":"Клиент ИИ-чата с вашими собственными ключами API (Anthropic, OpenAI, Google, совместимые с OpenAI), с поиском и экспортом в Markdown; «агенты» — это промпты. Требуется интернет; ключи хранятся в незашифрованном виде.","tags":["агенты"]},"VoiceAtelier":{"line":"Послушайте, как звучат сотни синтетических голосов на десятках языков, и узнайте, как делается аудиокнига. Онлайн-образец отправляет текст внешним сервисам только с вашего разрешения.","detail":"Каталог из 427 нейронных голосов (141 локаль) и руководство по аудиокнигам. Онлайн-образец отправляет текст на реле и в Microsoft, только с вашего согласия. Не студия TTS.","tags":["голос"]},"Trusa-fara-frontiere":{"line":"Набор из 15 небольших повседневных инструментов: заметки, таблица, Markdown, пароли, финансовый журнал и другое. Официально не связан с YunoHost, который вдохновил категории.","detail":"Набор из 15 небольших модулей, написанных с нуля (заметки, таблица, Markdown, пароли, журнал финансов и другие), по мотивам категорий приложений YunoHost; не аффилирован.","tags":["утилиты"]},"API-fara-frontiere":{"line":"Погода, снимки NASA, положение МКС и десятки живых данных в одном месте. Нужен интернет; с реальными сервисами не проверялось.","detail":"52 виджета: 47 поверх публичных API (нужен интернет; при открытии онлайн автоматически обращается к Open-Meteo, NASA и ISS) и 5 локальных утилит. Не проверено на реальных серверах.","tags":["API"]},"OmniHost":{"line":"Большой набор из более чем ста рабочих инструментов в одном месте. Обращается к четырём внешним сервисам; подробности в README.","detail":"Пакет для продуктивности (~4 МБ, 141 модуль). Обращается к четырём внешним хостам; см. README.","tags":["набор"]},"VNTV":{"line":"Воспроизводите трейлеры VideoNeat как непрерывный телеканал. Нужен интернет; в режиме P2P ваш адрес виден другим зрителям.","detail":"Трейлеры VideoNeat как непрерывная телепрограмма, плюс дополнение для Stremio. Требуется интернет (videoneat.com, videos.trom.tf); в режиме P2P ваш IP виден другим зрителям.","tags":["медиа","MIT"]},"OSATURA":{"line":"Оживляйте 2D-рисунки: привяжите их к «скелету», приведите в движение и экспортируйте анимацию в нескольких форматах. Альфа-версия, пока мало опробована.","detail":"Движок 2D-векторного рига и анимации на Rust (кости, IK, скиннинг, физика, конечные автоматы) с браузерной студией и экспортом в SVG, PNG, GIF, Lottie и glTF. Нативная программа (командная строка + студия) и модуль WebAssembly, не один HTML-файл; альфа-версия, пользователи почти не пробовали. Лицензии: библиотеки MPL-2.0, CLI AGPL-3.0-or-later.","tags":["анимация","MPL/AGPL"]},"OAZA":{"line":"340 бесплатных веб-сервисов, в основном без аккаунта, в одном каталоге. Список проверен в июне 2026 года, но не автоматически.","detail":"Каталог из 340 бесплатных сторонних веб-сервисов, обычно доступных без аккаунта (автоматически не проверяются; проверено в июне 2026 года).","tags":["сервисы"]},"VaultCrypt":{"line":"Есть что спрятать от посторонних глаз? Защищайте файлы и тексты паролем прямо в браузере. Потерянный пароль восстановить нельзя.","detail":"Шифрование файлов и текста AES-256-GCM в браузере. Независимый аудит не проводился; утерянный пароль восстановить нельзя.","tags":["безопасность"]},"Akasha":{"line":"Блокнот, работающий без интернета, с тегами, поиском и ссылками между страницами. Чтобы ничего не потерять, скачивайте свежую копию файла.","detail":"Офлайн-заметки в одном файле, с тегами, поиском и ссылками [[Название]]; чтобы сохранить свои данные, скачайте свежую копию файла (квайн).","tags":["заметки"]},"CLEPSIDRA":{"line":"Часы обратного отсчёта, будильник и расписания для будних и выходных дней. Учитывает праздники и ваши собственные события.","detail":"Обратные часы, будильник, расписания для будней и выходных, праздники, события.","tags":["время"]},"Origami":{"line":"Учитесь складывать бумагу шаг за шагом: обозначения, техники и иллюстрированные модели. Приложение запоминает, где вы остановились.","detail":"Руководство по оригами: обозначения, техники, пошаговые модели, прогресс сохраняется локально.","tags":["искусство"]},"Zicala":{"line":"Каждый день — одна румынская пословица из коллекции в 550 штук. Можно искать и сохранять избранные; комментарии написаны с помощью ИИ.","detail":"550 румынских пословиц с пословицей дня, поиском и экспортом/импортом избранного; комментарии SWOT/TOWS созданы с помощью ИИ.","tags":["культура"]},"Limpezimea":{"line":"Читайте научно-фантастический роман «Limpezimea» на семи языках. Сопроводительная хроника и критическое исследование написаны с помощью ИИ (Claude).","detail":"Научно-фантастический роман «Limpezimea» на 7 языках, читательское издание. Критический аппарат (хроника, исследование) написан с помощью ИИ (Claude).","tags":["литература"]},"Nota-Zero":{"line":"Спекулятивная фантастическая история о теории струн на румынском, английском и французском, с заметками, объясняющими научные идеи. Это вымысел, а не академический источник.","detail":"Рассказ спекулятивной фантастики о теории струн на румынском, английском и французском языках, с поясняющими научными примечаниями (художественная литература, не академический источник).","tags":["литература"]},"Pendulul":{"line":"Планета качается между тремя звёздами и чёрной дырой: девятитомный научно-фантастический роман, написанный Alexio вместе с Claude. 3D-симуляция, читалка с сохранением для чтения офлайн, EPUB и PDF.","detail":"Девятитомный научно-фантастический роман Alexio, написанный совместно с Claude: планета колеблется между тремя звёздами и чёрной дырой. Включает 3D-симуляцию и читалку книги в одном HTML-файле, который можно сохранить и читать офлайн, а также EPUB и PDF.","tags":["литература"]},"PrintreInteligente":{"line":"Войдите в интерактивный научно-фантастический роман с героями, вдохновлёнными экипажем «Артемиды-2». Обзоры вымышлены; функции перевода, голоса и ИИ используют внешние сервисы.","detail":"Интерактивный научно-фантастический роман, художественное произведение с персонажами, вдохновлёнными экипажем Artemis 2; рецензии вымышлены. Перевод, онлайн-озвучивание и функции ИИ используют внешние сервисы.","tags":["литература"]},"BorderlessMelodies":{"line":"Слушайте самосочиняющуюся музыку прямо в браузере. Можно экспортировать в аудио; есть таймер сна.","detail":"Процедурная музыка на Web Audio с экспортом аудио и таймером сна.","tags":["музыка"]},"EcoulSpectral":{"line":"Посмотрите на звук как на изображение, выделите мешающую часть и отделите или удалите её. Есть шумоподавление, обнаружение звуков и сохранение в WAV.","detail":"Локальный редактор спектрограмм: отметьте область время—частота и выделите или удалите её; обнаружение голоса, шумоподавление, экспорт в WAV.","tags":["аудио"]},"Constelar":{"line":"Общайтесь с виртуальными друзьями, которые помнят ваши разговоры. По умолчанию они отвечают по простым правилам; настоящий ИИ — только если вы выберете провайдера, и тогда ваши сообщения уходят ему. Только для взрослых.","detail":"Диалоговые компаньоны с локальной памятью. По умолчанию простой движок на правилах; настоящий ИИ — только если вы выберете провайдера (сообщения отправляются ему). Для взрослых; не заменяет терапию.","tags":["ИИ"]},"Tarot":{"line":"Изучайте историю таро, символы карт и то, как их читают, как культурное явление. Интерактивный курс в вашем темпе.","detail":"Интерактивный курс: история, символы и толкование карт как культурного явления.","tags":["культура"]},"Numerologie":{"line":"Изучайте нумерологию как символическую традицию на четырёх уровнях, с упражнениями, словарём, дневником и калькулятором. Представлено без научного подтверждения.","detail":"Интерактивный курс по нумерологии как символической традиции: четыре уровня, упражнения, глоссарий, дневник и калькулятор; представлен без научного подтверждения.","tags":["культура"]},"PUNCTUM":{"line":"Образовательный атлас акупрессуры и точечных методов: более 400 точек на интерактивных картах, рутины самопомощи с управляемыми сеансами, доказательства и безопасность. Не заменяет врача.","detail":"Образовательный атлас точечных терапий (иглоукалывание, акупрессура, прижигание полынью, баночный массаж, аурикулотерапия, рефлексотерапия и другие): 410 точек на 14 меридианах, 60 вариантов с уровнем доказательности, карты в SVG, состояния и комплексы упражнений, курс, викторина, карточки и личные проверки безопасности.","tags":["здоровье","доказательства"]},"Reiki":{"line":"Узнайте, что такое рэйки, духовная практика, и что говорят исследования: достаточных доказательств эффекта сверх расслабления не найдено. Не заменяет врача.","detail":"Курс по Рэйки, духовной практике: обзоры не находят достаточных доказательств какого-либо эффекта помимо расслабления/плацебо; не заменяет врача.","tags":["культура"]},"Bioenergoterapie":{"line":"Курс, объясняющий, что такое биоэнергетическая терапия и откуда она пришла. Научных доказательств лечебного действия практики нет; не заменяет врача.","detail":"Курс по биоэнерготерапии, практике без научных доказательств исцеления; не заменяет врача.","tags":["культура"]},"CHIROMANTIA":{"line":"Интерактивный атлас хиромантии: карта ладони с линиями, холмами, пальцами и типами рук, читаемая как культурная традиция; с разделом о науке и критическом мышлении. Научного подтверждения нет.","detail":"Интерактивный атлас хиромантии: карта ладони в SVG (левая/правая), линии, холмы, пальцы, типы рук, отпечатки пальцев, измерения 2D:4D, управляемое чтение, карточки, викторина, слепой тест Барнума и симулятор холодного чтения; каждое утверждение сопровождается уровнем доказательности.","tags":["хиромантия","культура"]},"Radiestezie":{"line":"Пройдите 18 уровней о поиске воды лозой со словарём, дневником практики и международными приложениями. С самого начала указывает, что научного подтверждения нет.","detail":"Курс из 18 уровней по лозоходству с глоссарием, журналом практики и международными приложениями; с самого начала заявляет, что не имеет научного подтверждения.","tags":["культура"]},"Inforenergetica":{"line":"Узнайте в структурированном курсе, что утверждает инфоэнергетика — нетрадиционная практика. Научного подтверждения нет; не медицинская рекомендация.","detail":"Курс по инфоэнергетике, нетрадиционной практике без научного подтверждения; не медицинская рекомендация.","tags":["культура"]},"ECLIPSA":{"line":"Узнайте, в какой астрологический дом вашей натальной карты попадает затмение, и о следующих 12 затмениях. Расчёт приблизительный, толкование символическое; научного подтверждения нет.","detail":"В какой астрологический дом попадает затмение на натальной карте, плюс следующие 12 затмений. Локальный приближённый астрономический расчёт; символическая интерпретация, у астрологии нет научного подтверждения.","tags":["астрология"]},"Afrodisiace-fara-frontiere":{"line":"Читайте о 22 продуктах и растениях, традиционно связываемых с желанием, с уровнем доказательности для каждого. Культурный справочник для взрослых, не медицинская рекомендация.","detail":"Культурный путеводитель по 22 продуктам и растениям, традиционно связываемым с желанием, с уровнем доказательности для каждой записи. Образовательный материал, не медицинская рекомендация.","tags":["культура"]},"CalmWaves":{"line":"Фоновая музыка для расслабления и сна, создаваемая на лету. Не медицинское устройство; раздел об исследованиях независимо не проверялся. Проконсультируйтесь с врачом (эпилепсия).","detail":"Генеративная эмбиент-музыка для расслабления/сна. Не медицинское изделие; раздел об исследованиях независимо не проверен. Проконсультируйтесь с врачом (эпилепсия).","tags":["аудио"]},"ASMR":{"line":"Составьте собственный расслабляющий звуковой пейзаж из слоёв атмосферы, звуков прикосновений и бинауральных ритмов. Есть таймер сна, смесью можно поделиться.","detail":"Микшер звуков для расслабления, генерируемых в реальном времени (Web Audio): фоновые слои, звуки прикосновений, бинауральные ритмы и таймер сна; микс можно делиться.","tags":["аудио"]},"NOMIA":{"line":"Каким мог бы быть первый контакт между людьми, ИИ и другими видами разума? 1001 воображаемый сценарий; вымысел, а не реальность. Работает и без интернета.","detail":"Концептуальный симулятор протоколов контакта Человек—ИИ—NHI, 1001 запись, спутник антологии «Printre inteligențe». Вымысел/гипотезы, не проверенные факты; офлайн-PWA, RO/EN.","tags":["фантастика","спекуляция","PWA"]},"ValeaPlopului1972":{"line":"Посмотрите на случай с НЛО 1972 года снаружи, изнутри и в симуляции, воссозданный в 3D. Это воображаемая гипотеза, а не доказательство.","detail":"3D-реконструкция случая UAP в Валя-Плопулуй (1972): внешний вид, симуляция, воображаемый интерьер. Спекулятивно, на основе непроверенных публичных источников, без согласия названных лиц; не является доказательством.","tags":["НЛО","3D","вымысел"]},"HoroScop":{"line":"Рассчитайте положения планет для даты и места, затем изучите натальную карту, аспекты и совместимость. Символическая астрология, научной основы нет. Работает офлайн.","detail":"Офлайн-личная эфемерида: положения планет вычисляются в браузере (пониженная точность), натальная карта, аспекты, синастрия. Символическая астрология, без научного подтверждения; лицензия MIT.","tags":["астрология","эфемериды","офлайн"]},"Aurora":{"line":"Слушайте успокаивающие тона и мягко пульсирующие звуки и следуйте дыхательной подсказке. Только для расслабления, не лечение. Работает без интернета.","detail":"Звуковое святилище: тона чакр, бинауральные ритмы и руководство по дыханию, офлайн. Только для расслабления, не медицина; частоты не имеют научного подтверждения. Лицензия MIT; независимый проект.","tags":["медитация","аудио","расслабление"]},"NumeroLogIA":{"line":"Узнайте, что нумерология, китайская астрология БаЦзы и биоритмы говорят о вашей дате рождения; каждый расчёт объяснён по шагам. Символическая система, научной основы нет.","detail":"Пифагорейская/халдейская нумерология, БаЦзы и биоритмы на 7 языках, пошаговые расчёты, портреты можно экспортировать в JSON; необязательный ИИ-оракул через вашу собственную модель. Символическая система, без научного подтверждения; лицензия MIT.","tags":["нумерология","ИИ","офлайн"]},"FrequencyLaboratory":{"line":"Пробуйте звуки, эффекты и тесты слуха в небольшой звуковой лаборатории. «Терапевтические» эффекты не доказаны; не заменяет врача. Работает офлайн.","detail":"Аудиолаборатория в браузере (осцилляторы, бинауральные ритмы, эффекты, анализаторы, тесты слуха), офлайн. Только для информации: «терапевтические» пресеты не имеют доказанного медицинского эффекта; не медицинское изделие.","tags":["аудио","лаборатория","офлайн"]},"generator-frecvente":{"line":"Создавайте чистые тона и пульсирующие пары, слушайте известные пресеты и приблизительно проверьте свой слух. Не медицинское устройство. Работает офлайн.","detail":"Генератор тонов в браузере (бинауральные, секвенсор, эквалайзер, ориентировочный тест слуха, поиск пресетов), офлайн. Только для информации: пресеты Сольфеджио/Шумана не имеют научного подтверждения; не медицинское изделие.","tags":["аудио","генератор","офлайн"]},"ACORDAJ":{"line":"Просматривайте более тысячи духовных курсов и посвящений с историческим контекстом и критическим взглядом. Не связан с сайтом-источником, научного подтверждения нет. Работает офлайн.","detail":"Офлайн-атлас из 1134 духовных курсов/инициаций (список с cursurispirituale.webnode.ro, не аффилирован), с историческим контекстом и критическим осмыслением; без научного подтверждения.","tags":["духовность","атлас","критическое мышление"]},"Profund":{"line":"150 вопросов, которые выводят разговор за рамки светской беседы — между друзьями или в семье. Играйте на экране или распечатайте, с необязательным таймером.","detail":"Игра из 150 вопросов для содержательных разговоров (RO/EN/FR), онлайн или в печатном виде, с игроками и необязательным таймером; адаптирована с deepcards.org, оригиналы остаются собственностью правообладателей (MIT — только для кода и оригинальной части).","tags":["беседа","карточки","trade-free"]},"Universul-Observabil":{"line":"Насколько велика наблюдаемая Вселенная? Сравните три карты (линейную, плоскую, в пространстве) и выполняйте космологические расчёты. Цифры независимо не проверялись.","detail":"Страница-хаб, представляющая и сравнивающая 1D-, 2D- и 3D-визуализации наблюдаемой Вселенной, с офлайн-космологическим калькулятором; цифры и рекорды взяты из каталога за май 2026 года, независимо не проверены. RO/EN.","tags":["астрономия","космология","визуализация"]},"Universul-Observabil-1D":{"line":"Путешествуйте от нас до края видимой Вселенной мимо 112 галактик, расположенных на одной оси. Ироничный тон, округлённые значения, образовательная цель.","detail":"1D-карта наблюдаемой Вселенной: 112 галактик на радиальной оси (время, расстояние, красное смещение), с таблицей данных и экспортом в CSV. Образовательная, с ироничным тоном; округлённые значения, рекорды на дату каталога (май 2026).","tags":["астрономия","космология","визуализация"]},"Universul-Observabil-2D":{"line":"Карта галактик в сатирическом издании «Плоская Земля»: это шутка, Земля не плоская. Приближайте среди 111 галактик; расстояния приблизительны. Работает офлайн.","detail":"Интерактивная 2D-карта наблюдаемой Вселенной (111 галактик, логарифмическая шкала, данные JWST) в сатирической версии «Плоская Земля»: пародия, Земля не плоская; расстояния приблизительные. RO/EN, офлайн.","tags":["астрономия","сатира","космология"]},"Universul-Observabil-3D":{"line":"Летайте среди более чем 115 галактик на 3D-карте с экскурсиями и миссиями. Значения приблизительны.","detail":"Интерактивная 3D-карта (WebGL) наблюдаемой Вселенной: более 115 галактик, 12 горизонтов, 30 экскурсий, задания в путеводителе, экспорт в GLB/CSV/BibTeX. Приблизительные значения; рекорды JWST на май 2026 года.","tags":["астрономия","космология","3D"]},"QSO":{"line":"Ведите журнал радиосвязей вашей любительской радиостанции со временем UTC, локаторами и статистикой. Неофициально; расчёты приблизительны.","detail":"Неофициальный журнал любительской радиостанции: QSO с часами UTC, импорт/экспорт ADIF 3.1, локаторы Maidenhead, проверка дубликатов, статистика. Неполная таблица префиксов (не DXCC); приближённые расчёты.","tags":["радио","журнал"]},"Curatitor":{"line":"Посмотрите, что раскрывают ваши фотографии и файлы (место, камера, автор), и удалите эти данные перед отправкой. Не скрывает лица и другое видимое содержимое.","detail":"Показывает и удаляет метаданные файлов локально (GPS, камера, автор, программа) без перекодирования пикселей или звука и повторно проверяет результат. Не анонимизирует содержимое (лица, шум сенсора).","tags":["метаданные","приватность"]},"Poteca":{"line":"Откройте треки, записанные в походе или на велосипеде, и посмотрите расстояние, набор высоты и профиль высот. Можно обрезать или объединять. Карты нет; набор высоты оценочный.","detail":"Просмотрщик и редактор треков GPX/GeoJSON/KML/CSV: статистика, профиль высот, вырезание, объединение, упрощение, экспорт. Без базовой карты; набор и потеря высоты — оценки.","tags":["GPX","треки"]},"Orar":{"line":"Календарь и недельный планировщик с официальными праздниками Румынии, с просмотром по дням, неделям или месяцам. Будильники звонят, только пока страница открыта.","detail":"Календарь и недельный планировщик: виды месяц/неделя/день/повестка, повторения RFC 5545, часовые пояса, государственные праздники Румынии, импорт/экспорт .ics. Будильники звонят только пока вкладка открыта.","tags":["календарь","время"]},"Alfabete":{"line":"Учите и тренируйте азбуку Морзе, шрифт Брайля, фонетический алфавит, флажную семафорную азбуку и старинные шифры, затем распечатайте страницу. Старинные шифры не защищают секреты.","detail":"Справочник, конвертер, тренажёр и печатный лист для азбуки Морзе, шрифта Брайля (ступень 1), фонетических алфавитов, семафора, Бодо, систем счисления и классических шифров. Классические шифры не обеспечивают безопасности.","tags":["коды","обучение"]},"Fabrica":{"line":"Пишите курс простым текстом и превращайте его в страницу с уроками, итоговым тестом и сертификатом для печати. Сертификат не имеет официальной силы.","detail":"Фабрика курсов и викторин: напишите курс в простом Markdown и экспортируйте его как один автономный HTML-файл с локальным прогрессом, итоговым тестом и печатным сертификатом (без аккредитационной силы).","tags":["курсы","создание"]},"Bolta":{"line":"Каким было небо над головой в любом месте и в любой день между 1900 и 2100 годами? Солнце, Луна, планеты и звёзды, а также затмение 2027 года. Значения рассчитаны, неофициально. Работает офлайн.","detail":"Офлайн-планетарий для любого места и времени между 1900 и 2100 годами: Солнце, Луна, планеты, 1627 звёзд, созвездия, события и страница о затмении 2027 года. Вычисленные значения, не официальные.","tags":["астрономия","планетарий"]},"BRAZDA":{"line":"Расшифруйте Золотую пластинку «Вояджера» шаг за шагом, затем закодируйте новый диск для зонда, запускаемого сейчас. Изображения на первых шагах схематичны, это не изображения NASA.","detail":"12-шаговый декодер и кодировщик Золотой пластинки «Вояджера»: скорость, водородные часы, карта пульсаров, сигнал изображения, калибровка по окружности, построчное декодирование, цвет, собственный файл, вклады и кодирование диска 2026–2027 годов.","tags":["Вояджер","сигнал"]},"Arbore":{"line":"Стройте семейное древо с людьми, семьями, временной шкалой и румынским калькулятором родства. Данные остаются только в этом браузере, синхронизации нет.","detail":"Локальная генеалогия: люди, семьи, импорт/экспорт GEDCOM 5.5.1, диаграммы SVG, временная шкала, калькулятор родства (только румынская терминология). Без синхронизации; данные остаются в этом браузере.","tags":["родословная","GEDCOM"]},"Gospodar":{"line":"Учитывайте домашние деньги: счета, расходы, помесячные бюджеты и отчёты. Аккаунт не нужен, но если потеряете пароль, потеряете данные. Не финансовая рекомендация.","detail":"Локальный семейный бюджет: счета, категории, операции, импорт CSV, ежемесячные бюджеты, отчёты и калькуляторы с прозрачными формулами. Без аккаунта и синхронизации; потерянный пароль означает потерянные данные. Не финансовая рекомендация.","tags":["бюджет","личные финансы"]},"Decibel":{"line":"Измерьте, насколько громок окружающий шум, и посмотрите, из каких звуков он состоит. Есть и ориентировочный тест слуха. Не сертифицированный прибор; результаты зависят от микрофона.","detail":"Шумомер, анализатор спектра (1/3 октавы, FFT) и ориентировочный тест слуха. Не сертифицированный прибор, без юридической или медицинской силы; показания зависят от микрофона и калибровки.","tags":["звук","измерение"]},"Provenienta":{"line":"Есть изображение, и вы хотите знать, кто его подписал и какие правки заявил? Проверьте встроенную цифровую подпись. Экспериментально, проверено только на примерах файлов.","detail":"Локальная экспериментальная проверка C2PA / Content Credentials: показывает, кто подписал и какие правки были заявлены, и проверяет подпись и привязку к байтам файла. Протестировано только на синтетических файлах; без списка доверия.","tags":["C2PA","происхождение"]},"Lexicon":{"line":"Принесите свои словари и ищите слова, даже если пишете без диакритики или с ошибками. Поставляется лишь с небольшим демонстрационным набором. Работает офлайн.","detail":"Офлайн-движок словарей: подключайте собственные словари (TSV/CSV, JSON, StarDict, dictd, XDXF) и ищите по префиксу, без учёта диакритики, нечётко или по полному тексту. Встроенный набор (345 статей) — демонстрация, не полный словарь.","tags":["словарь","язык"]},"VERIGA":{"line":"Находит битые ссылки и осиротевшие файлы на сайте или в папке. Работает в Windows, macOS и Linux; нужно немного опыта работы с компьютером.","detail":"Проверка ссылок (clean-room) для сайтов и локальных папок, написана на Rust: командная строка, нативное настольное приложение (egui) и версия в одном HTML-файле. Проверяет ссылки HTML и CSS, перенаправления, якоря #fragment, файлы-сироты, robots.txt и sitemap. Windows, macOS и Linux; лицензия MIT.","tags":["проверка ссылок","MIT"]},"TEZAUR":{"line":"Помощник по диссертации, который пишет только на основе ваших собственных книг и статей, с проверяемыми цитатами. Работает на вашем компьютере; документы никогда не покидают его. В разработке.","detail":"Локальный исследовательский помощник для написания диссертации, написан на Rust, с ответами на основе цитат: индексирует ваши книги и статьи (PDF, EPUB, DOCX, txt), извлекает фрагменты и пишет только по ним, с проверенными цитатами [n] и списком литературы. Работает на вашем компьютере с локальной моделью (Ollama, Jan, LM Studio); ваши документы его не покидают. Версия 0.x; лицензия MIT.","tags":["исследования","MIT"]},"LegatorOCR":{"line":"Отсканируйте книгу и получите чистый PDF с исправленными страницами и текстом с поиском. Работает в Windows, macOS и Linux; ваши сканы остаются у вас.","detail":"Clean-room постобработчик на Rust для отсканированных книг: разделяет развороты, выравнивает перекос, обрезает, задаёт поля, очищает и бинаризует, затем экспортирует PDF или изображения с текстовым слоем OCR для поиска. Графическое приложение (Windows, macOS, Linux) и командная строка, на 8 языках. Для распознавания текста (OCR) нужна отдельная программа Tesseract; всё остальное работает без неё. Версия 0.x; лицензия MIT.","tags":["сканирование","MIT"]},"Fenarium":{"line":"Атлас и мастерская субъективных восприятий по всем чувствам, начиная с фосфенизма: курс из 13 модулей, управляемые эксперименты, визуальный симулятор и лаборатория А/Б-самоэкспериментов с рандомизацией. Образовательное, не медицинское устройство.","detail":"Атлас феноменов (фосфены, остаточные образы, звуки, похожие на тиннитус, и другие), курс из 13 модулей, лаборатория самоэксперимента; не медицинское изделие.","tags":["восприятие","MIT"]},"MENSURA":{"line":"Измерьте IQ, EQ, CQ, RQ, исполнительные функции и чувства в 6 областях с помощью 18 тестов, составных индексов и 95%-ных доверительных интервалов. Предварительные нормы, только ориентировочно, не диагноз.","detail":"18 тестов в 6 областях (IQ, EQ, CQ, RQ, исполнительные функции, органы чувств), показатели с доверительными интервалами, экспорт/импорт JSON; предварительные нормы.","tags":["тесты","MIT"]},"Cronosala":{"line":"Таймеры для спортзала: отдых между подходами, HIIT, Табата, EMOM, AMRAP, круги и метроном, а также дневник тренировок с кг и повторениями.","detail":"Таймеры для спортзала и журнал тренировок в одном HTML-файле: адаптивный отдых между подходами, Interval/HIIT, Tabata, EMOM, AMRAP, круговые тренировки по станциям, темп, метроном, 4-недельная ежемесячная программа, каталог упражнений и QR-коды для тренажёров. Данные остаются в браузере; интерфейс на румынском.","tags":["спорт","время"]},"ScutSonor":{"line":"Громкий звук и стробоскоп фонарика для встреч с агрессивными собаками, плюс руководство по поведению. Это помощь, а не гарантированная защита.","detail":"Генерирует свип 2–8 кГц, экспериментальный ультразвук, сирену и тест динамиков, с ограничителем, сохраняющим громкость, стробоскоп фонарика (2,5 Гц), дневной режим и руководство по безопасности. Один файл, без отслеживания. Доказательства того, что звук отпугивает собак, слабые.","tags":["безопасность","звук"]},"MIRAJ":{"line":"Как видит сетчатка и как мозг строит изображение: ямка, слепое пятно, иллюзии и тест, на трёх уровнях.","detail":"Интерактивное объяснение зрения на трёх уровнях (начальном, среднем, продвинутом): сетчатка, фовеа, слепое пятно, оптические иллюзии, резюме и викторина из 10 вопросов. Один файл, интерфейс на румынском и английском.","tags":["зрение","обучение"]},"ANTROPOS":{"line":"Ориентировочный научный профиль, вычисляемый локально: биологический возраст PhenoAge, голос, почерк, рисунок часов, личность по TIPI и время реакции.","detail":"Образовательный скрининговый инструмент, не диагноз: биологический возраст PhenoAge с защитой от неправдоподобных значений, анализ голоса, графометрия почерка, тесты с часами и рисунком человека, TIPI, тесты реакции, печатный отчёт и экспорт в JSON. Данные остаются в браузере.","tags":["скрининг","биология"]},"DESCANTAR":{"line":"Гадание на 41 бобе (метод 3×3, олтенский вариант) и 12 традиционных заговоров как предмет фольклорного исследования.","detail":"Румынское гадание на бобах тремя методами (3×3 по книге, Олтения, три кучки), прочтение по Голове, Сердцу и Ногам, 12 традиционных заговоров, фаза Луны, счётчик повторений, генератор заговоров, история и руководство, которое можно скопировать. Фольклорное содержание переведено на 8 языков с помощью ИИ, носителями языка не проверено.","tags":["фольклор","бобы"]},"Index-fara-frontiere":{"line":"Каталог однофайловых HTML-приложений: коллекция chiuta.github.io и внешние источники, с поиском и тегами.","detail":"Восемь проектов из коллекции автора и восемь внешних ресурсов с чёткой пометкой, с живым поиском, кликабельными тегами, переключателем RO/EN, тёмной/светлой темой и записью, которая каталогизирует саму себя. Без сетевых запросов. Статический снимок от 5 июля 2026 года.","tags":["каталог","источники"]},"DECUPAJ":{"line":"Превращайте подкаст, аудио или видео в вертикальные клипы с субтитрами прямо в браузере, без аккаунта и водяных знаков. Ваши файлы никогда не покидают устройство.","detail":"Вертикальные ролики из подкаста (аудио или видео) в одном HTML-файле: выбор фрагмента на волновой форме, подсказки моментов, локальная транскрипция с Whisper, стилизованные субтитры, 4 соотношения сторон (9:16, 4:5, 1:1, 16:9), очередь экспорта и MP4 через WebCodecs. Интерфейс на 8 языках.","tags":["reels","видео"]},"LECTOR":{"line":"Книги, озвученные прямо в браузере: EPUB, DOCX, PDF, TXT или вставленный текст, без аккаунта и сервера. Текст никогда не покидает ваше устройство.","detail":"Слушайте книги в озвучке из одного HTML-файла: EPUB, DOCX, PDF (с румынским OCR для сканов), TXT; голоса устройства или Piper ro_RO, подсветка произносимого слова, таймер сна, главы, закладки, словарь произношения, локальная библиотека и темы, удобные при дислексии. Интерфейс на 8 языках.","tags":["аудио","книги"]},"FARFURIA":{"line":"Бесплатный цифровой диетолог: персональные калории и макронутриенты, план питания на 7 дней, дневник питания и отслеживание веса. Не заменяет врача или диетолога.","detail":"Цифровой диетолог в одном HTML-файле: цели по калориям и макронутриентам (Mifflin–St Jeor, уровень активности, цель), 7-дневный план питания с фильтрами по диете и аллергенам, база продуктов, дневник питания и отслеживание веса. Правила безопасности для несовершеннолетних, при расстройствах пищевого поведения в анамнезе и болезни почек. Интерфейс на 8 языках.","tags":["питание","здоровье"]},"VITALIS":{"line":"Личный помощник по здоровью, долголетию и биохакингу: девять разделов, ранжированных по доказательности, калькуляторы, оценка образа жизни и ежедневный ритуал. Не медицинская рекомендация.","detail":"Спутник здоровья и долголетия в одном HTML-файле: девять столпов, ранжированных по доказательности, калькуляторы (HOMA-IR, TyG, отношение талии к росту, Mifflin–St Jeor, зоны пульса, циклы сна, белок), таймер голодания, дыхательный пейсер, показатель 360 с радарной диаграммой, референсные диапазоны биомаркеров и трекер ежедневного ритуала. Неофициальный спутник мероприятия BioHacking360. Интерфейс на 8 языках.","tags":["здоровье","долголетие"]},"REZONANTA":{"line":"Руководство и инструменты по коммуникации и медиа: сообщение, каналы, пресс-релиз, интервью, ясность, план и кризис.","detail":"Как сделать так, чтобы вас слушали, в одном HTML-файле: 12 принципов с практической проверкой, «дом сообщения» (30-секундная подача, публикация, короткая и устная версии), рекомендации по медиаканалам, генератор пресс-релиза по принципу перевёрнутой пирамиды, лист интервью, анализатор ясности текста, план коммуникации с экспортом в текст/CSV и шаги первого часа кризиса. Интерфейс на 8 языках.","tags":["коммуникация","медиа"]},"Claritas":{"line":"Универсальное расширение браузера для доступности: коррекция контраста, режим чтения, озвучивание и проверка WCAG. Без телеметрии, без сети, без аккаунта.","detail":"Бесплатное расширение доступности для браузера: автоматическое исправление контраста (WCAG AA/AAA), высококонтрастные темы, фильтры для дальтоников, увеличенный текст и шрифты, удобные при дислексии, линейка, маска и лупа для чтения, режим чтения, чтение вслух, крупные цели для щелчка и сканирование одним переключателем, аудит WCAG 2.2, локальные снимки экрана и запись экрана. Для Chromium, Firefox и Safari; интерфейс на 8 языках.","tags":["доступность","расширение"]},"TurboCursa":{"line":"Псевдо-3D аркадная гоночная игра, написанная на Rust: ландшафты, создаваемые из зерна, 11 режимов, карьера в лиге и 2 игрока. Оригинальная; кода и ресурсов из другой игры нет.","detail":"Clean-room псевдо-3D аркадные гонки на Rust: оригинальный движок, графика, музыка и название, всё генерируется из зерна (19 ландшафтов), кампания, заезд на время, бесконечный режим, Rush Hour, слалом, зеркало, Blackout, Zen, против CPU, разделённый экран на двоих и карьера по дивизионам. Работает нативно или как веб-файл; интерфейс на 8 языках.","tags":["гонки","Rust"]},"ANTENA":{"line":"В разработке: решатель проволочных антенн, совместимый с NEC-2 (метод моментов), с интерфейсом в браузере. Пока только скелет пре-альфа.","detail":"В разработке: решатель проволочных антенн, совместимый с NEC-2 (метод моментов), с браузерным интерфейсом. Пока только скелет в стадии пре-альфа.","tags":["радио","антенны"]},"ARBITRU":{"line":"В разработке: универсальный движок правил для настольных, карточных, костяных и головоломных игр с декларативным языком правил. Пока только скелет пре-альфа.","detail":"В разработке: универсальный движок правил для настольных, карточных, игр в кости и головоломок с декларативным языком правил. Пока только скелет в стадии пре-альфа.","tags":["игры","правила"]},"ASTROLABIU":{"line":"В разработке: движок небесных событий на чистом Rust (шкалы времени, затмения, восходы и закаты, календари). Пока только скелет пре-альфа.","detail":"В разработке: движок небесных событий (шкалы времени, затмения, восход и заход, календари) на чистом Rust. Пока только скелет в стадии пре-альфа.","tags":["астрономия","календари"]},"ECOGRAMA":{"line":"В разработке: редактор спектрограмм и реставрация звука: выделяйте на спектрограмме, восстанавливайте, экспортируйте. Пока только скелет пре-альфа.","detail":"В разработке: редактор спектрограмм и восстановление звука: выделение на спектрограмме, исправление, экспорт. Пока только скелет в стадии пре-альфа.","tags":["аудио","реставрация"]},"ecou-spectral-rs":{"line":"В разработке: нативный редактор спектрограмм на Rust с плагинами шумоподавления и обнаружения звуков. Есть каркас кода и формат плагинов, но законченных функций пока нет.","detail":"В разработке: нативный редактор спектрограмм на Rust с плагинами для шумоподавления и обнаружения голоса. Есть скелет кода и формат плагинов, но ещё ни одной готовой функции.","tags":["аудио","Rust"]},"MARTOR":{"line":"В разработке: судебный захват веб-страниц в WARC/WACZ с хешами, подписями и доверенными метками времени, проверяемый офлайн. Пока только скелет пре-альфа.","detail":"В разработке: судебно-технический веб-захват в WARC/WACZ с хешами, подписями и доверенными метками времени, проверяемый офлайн. Пока только скелет в стадии пре-альфа.","tags":["архивирование","доказательства"]},"NEAMURI":{"line":"В разработке: движок родства — от пути в семейном древе к правильному термину родства на многих языках. Пока только скелет пре-альфа.","detail":"В разработке: движок родства, от пути по семейному древу до правильного термина родства на многих языках. Пока только скелет в стадии пре-альфа.","tags":["родство","родословная"]},"TACTIL":{"line":"В разработке: слой тактильного вывода: форматы Брайля (BRF, Unicode), дисплеи, рельефные принтеры и вибрация сенсорного экрана. Пока только скелет пре-альфа.","detail":"В разработке: слой тактильного вывода: форматы Брайля (BRF, Unicode), дисплеи, эмбоссеры и вибрация сенсорного экрана. Пока только скелет в стадии пре-альфа.","tags":["Брайль","доступность"]},"atelier-verificare":{"line":"Проверяйте фотографии, видео, ссылки и домены в браузере, ничего не загружается: реальный тип файла и SHA-256, EXIF/GPS, XMP/IPTC, Content Credentials (только чтение), анализ уровня ошибок. Не может доказать, что фото настоящее. Альфа.","detail":"Набор инструментов проверки для журналистов и внимательных читателей, работающий локально. Добавьте изображения, видео, ссылки, домены или текст и получите выводы с уровнем настороженности по каждому: реальный тип файла, SHA-256, EXIF и положение GPS, XMP и IPTC, следы генераторов ИИ-изображений, манифесты Content Credentials (C2PA; читаются, не проверяются), анализ уровня ошибок для JPEG, метаданные видео с ключевыми кадрами для обратного поиска изображений и анатомия ссылки. Две необязательные сетевые проверки (сводка DNS, Internet Archive) выполняются только после того, как вы поставите флажок согласия. Отчёт (Markdown, JSON или PDF) перечисляет ограничения метода. Он не может доказать подлинность фотографии: отсутствие метаданных говорит мало, а метаданные можно подделать. Альфа; девять из одиннадцати проверок работают офлайн; файлы остаются в браузере.","tags":["журналистика","проверка","фотографии"]},"balanta":{"line":"Слепое сравнение моделей ИИ: вставьте ответы от двух до восьми моделей на 92 промпта на румынском, английском и венгерском, голосуйте за A или B и получайте рейтинг с интервалами. Альфа; работает офлайн.","detail":"Слепое сравнение ИИ-моделей на румынском языке. Вы сами вставляете ответы каждой модели (ничего не вызывается: ни ключей API, ни аккаунтов), приложение скрывает названия моделей внутри ответов, фиксирует порядок по зерну и записывает ваш голос. Рейтинг использует Брэдли—Терри и Эло с 95% бутстрэп-интервалами, а также долю побед, смещение позиции и таблицы очных встреч. Голоса и ответы — открытые файлы JSON Lines. При малом числе голосов или запросов рейтинг ничего общего не говорит. Альфа; данные остаются в браузере; без отслеживания.","tags":["ИИ","оценка"]},"calendarium":{"line":"Введите дату в одном из одиннадцати календарей (григорианском, юлианском, еврейском, хиджры, персидском, китайском, майя, марсианском…) и увидите её во всех остальных, с просмотром месяца. Альфа; работает офлайн.","detail":"Преобразует даты между одиннадцатью календарями (григорианский, юлианский, новоюлианский, еврейский, хиджры, персидский, коптский, эфиопский, китайский, майя и марсианская солнечная дата), показывает юлианский день, день недели и неделю ISO, и имеет вид месяца со вторым календарём под каждым днём. Включает румынские примечания (старый и новый стиль, переход 1919 года, Пасха) и атлас календарей, по одному плагину на календарь. Значения вычисляются, с заявленными ограничениями (календарь хиджры табличный; диапазоны защищены). Альфа, на 8 языках, работает офлайн; без отслеживания.","tags":["календари","время"]},"glosar":{"line":"Офлайн-словарь для арумынского, мегленорумынского и романи: ищите без диакритики, смотрите, каких основных слов не хватает, и добавляйте слова с источником и регистром. Альфа.","detail":"Словари малых и исчезающих языков, созданные их носителями. Ищет без учёта диакритики, показывает надёжность (черновик, с источником, проверено), имеет таблицу охвата из 50 базовых понятий и позволяет добавлять слова с источником, лицензией и записью (до 50 КБ). Экспортирует файлы TSV и Anki и файл вклада для проекта. Начальные списки невелики — числительные и несколько слов, каждое с опубликованным источником — и ни один носитель их ещё не проверял. Альфа; работает офлайн; данные остаются в браузере, пока вы их не скачаете.","tags":["языки","словари"]},"graiul":{"line":"Офлайн-архив румынского фольклора (пословицы, заговоры, загадки, колинды) с источником, уездом и согласием. Начинается с десяти пословиц; можно добавлять другие. Альфа.","detail":"Поиск без учёта диакритики с фильтрами по типу, уезду и надёжности; пословица дня (одинаковая для всех в данную дату), схематичная плиточная карта 41 уезда и Бухареста и форма добавления, требующая источник и, для заговоров и всего, что собрано от человека, согласие. Экспортирует файл вклада и TSV. Начальные данные — десять румынских пословиц из Wikiquote; ни одну не проверял фольклорист. Альфа; работает офлайн; данные остаются в браузере, пока вы их не скачаете.","tags":["фольклор","архив"]},"indicativ-international":{"line":"Готовьтесь к вопросам радиолюбительского экзамена с графиком повторения из пяти ящиков и пробными экзаменами на время; импортируйте пакеты вопросов в общем формате JSON. Включено 50 тренировочных вопросов; это не официальный банк. Альфа.","detail":"Тренажёр и симулятор экзамена по вопросам лицензии радиолюбителя с общим форматом пакетов, чтобы каждая страна могла добавить свой банк. «Тренировка» повторяет правильные ответы через 1, 3, 7, 14 и 30 дней и объясняет каждый ответ с указанием источника; «Экзамен» — тест на время с проходным баллом; «Пакеты» импортирует и проверяет пакеты и сохраняет резервную копию вашего прогресса. Встроенный пакет содержит 50 оригинальных тренировочных вопросов, написанных для этого проекта — не официальный банк — и ни одного пакета страны пока нет. Альфа; работает офлайн; прогресс остаётся в браузере.","tags":["радио","экзамены"]},"proiector-fara-frontiere":{"line":"Телефоны в классе превращаются в общий экран без сервера и аккаунтов: таймер, опрос, викторина, заметки и доска; сопряжение по QR-коду или вставленному тексту в одной сети. Альфа: на реальных телефонах пока не проверено.","detail":"Общий экран для класса, без сервера и без аккаунта. Учитель открывает страницу на проекторе; телефон каждого ученика подключается обменом кодом (кадры QR, фото кода или вставленный текст), до 30 телефонов одновременно. Включены пять занятий: таймер обратного отсчёта, опрос с живыми столбцами, викторина (вопросы из файла JSON, простого текста или CSV; правильный ответ остаётся на проекторе, пока не будет показан; бонус за скорость и таблица результатов), стикеры и доска с отдельным цветом для каждого телефона. Результаты можно сохранить в CSV, тексте или PNG. Каждое занятие работает в изолированном фрейме только с теми разрешениями, которые оно объявляет, а новое занятие — это один дескриптор и один скрипт. Учитель может заблокировать или удалить телефон и завершить сеанс; каждое устройство выбирает свой язык (восемь) и вид (тёмный, высокий контраст, крупный текст). Работает офлайн после открытия и может быть установлено. Альфа: протестировано в Chromium с реальными соединениями на одной машине, но не на реальных телефонах, других браузерах или школьных сетях. Сопряжение требует одной и той же локальной сети (без реле), показывает IP-адрес каждого устройства другому и не проверяет, кто находится на другом устройстве. Формат викторины «Undava» не поддерживается: спецификация не найдена.","tags":["класс","проекция","викторина"]},"regula":{"line":"Играйте в пять классических игр для двоих (мельница, алькерк, фанорона, му торере, хнефатафл) против компьютера или друга; добавляйте собственную игру в JSON. Альфа; работает офлайн.","detail":"Один движок правил для традиционных настольных игр: каждая игра — файл JSON, а текст правил на восьми языках генерируется из тех же данных, по которым играет движок, поэтому текст и игра не могут расходиться. Каждая сторона может быть человеком, случайным игроком или компьютером двух уровней; отмена, повтор, подсказка и запись ходов, которую можно скопировать. Вы можете вставить, проверить и сыграть в собственную игру. Игры — реконструкции, не турнирные правила, и каждая сообщает, насколько уверены её правила. Альфа; работает офлайн; без отслеживания.","tags":["игры","правила"]},"vietar-packs":{"line":"Просматривайте, импортируйте, проверяйте и создавайте региональные пакеты видов для VietAR: названия на нескольких языках, маркеры токсичности, похожие виды. Пять черновых стартовых пакетов на 71 вид. Альфа; работает офлайн.","detail":"Региональные пакеты видов для VietAR: названия на нескольких языках, пометка токсичности, опасные двойники и место для лицензированных фотографий и ссылок на звук. Просматривайте и ищите по пяти начальным пакетам (Румыния: растения и грибы, птицы, млекопитающие; Болгария и Молдова: скелеты), импортируйте пакет, проверяйте его по тем же правилам, что и репозиторий, или создайте пакет для школьного класса или клуба любителей природы. Начальные пакеты — черновики без фотографий и звуков, а «не отмечено как токсичное» никогда не означает «съедобное» или «безопасное». Приложение VietAR пока не может импортировать пакеты. Альфа; работает офлайн.","tags":["природа","виды"]},"PatruZeci":{"line":"Иллюстрированный анимированный атлас применений WD-40: руководство из 147 карточек и официальный список из 1993 применений, у каждого своя анимированная сцена. Неофициально, офлайн, без аккаунта.","detail":"Иллюстрированный анимированный атлас применений спрея WD-40 в одном офлайн-файле: руководство из 147 карточек в 14 категориях (с уровнем риска и тем, что делает спрей), официальный список «2000+ применений» с 1993 записями и раздел из 25 дополнительных применений, мифов и предупреждений из веб-статей. 131 вариант анимированных сцен, фильтры по категории и функции, интерфейс на 8 языках. Неофициальное, независимое приложение.","tags":["WD-40","сделай сам"]},"ODISEEA":{"line":"Документальный фильм примерно на 4,5 минуты о «Вояджерах-1 и -2» в одном HTML-файле: сцены генерируются на видеокарте, экспорт в 2D и 3D для VR-очков, на 8 языках.","detail":"Документальный фильм примерно на 4,5 минуты о зондах Voyager 1 и 2, в одном HTML-файле, который работает локально в браузере, без сервера и установки. Процедурные сцены, генерируемые на видеокарте (WebGL): планеты, зонд, ракета, антенна DSN, Золотая пластинка, гелиосфера, Бледно-голубая точка. Публичные изображения NASA/JPL и Wikimedia Commons или ваше собственное изображение для каждой сцены. Экспорт в 2D, половинном (1920×1080) и полном (3840×1080) 3D side-by-side и режим телефона для VR-очков, таких как VR BOX; эмбиент-музыка, генерируемая в браузере, необязательный дикторский текст. Интерфейс, дикторский текст, субтитры и титры на 8 языках.","tags":["Вояджер","документальный фильм"]},"EXIF-CURAT":{"line":"В разработке: инструмент на Rust с безопасными по памяти парсерами для просмотра и очистки скрытых данных в файлах (изображения, PDF, Office, видео: EXIF, GPS, XMP). Пока только скелет пре-альфа.","detail":"В разработке: инструмент для просмотра и удаления скрытых данных в файлах (изображения, PDF, Office, видео: EXIF, GPS, XMP) с безопасными по памяти парсерами, написан на Rust. Пока только скелет в стадии пре-альфа.","tags":["метаданные","приватность"]},"PORUMBEL":{"line":"Автоматически переносит снимки, сделанные на телефоне в Open Camera, в папку на компьютере, по одной папке на сеанс, и открывает их в LegatorOCR. Без аккаунта, без облака, без сторонних крейтов.","detail":"Небольшая программа на Rust без сторонних крейтов (Windows, macOS, Linux), которая переносит на ваш компьютер фотографии, снятые в Open Camera: по Wi-Fi (страница загрузки или WebDAV, с QR-кодом), через ADB (USB или Wi-Fi) или из синхронизируемой папки (Syncthing и др.). Она раскладывает фотографии по одной папке на сеанс съёмки и открывает каждый завершённый сеанс в LegatorOCR (разделение, выравнивание, обрезка, PDF с OCR). Локальная панель управления и команда «porumbel doctor» для диагностики; ничего не покидает вашу сеть. Версия 0.x; лицензия MIT.","tags":["фотографии","передача"]},"colibri-companion":{"line":"Дружелюбное настольное приложение для локального движка вывода colibri: выберите модель, подходящую вашему компьютеру, скачайте одним щелчком и общайтесь с ней. Без аккаунта, без облачного сервиса.","detail":"Настольное приложение на Rust для colibri (JustVugg/colibri): находит Python и colibri, показывает только модели, которые умещаются в память вашего компьютера, скачивает их с паузой и возобновлением, запускает локальный сервер и открывает чат (потоковые ответы, Markdown, сохранённые беседы, поиск, локальные документы и инструменты MCP с подтверждением каждого вызова). Панель Resources показывает процессор, память, видеокарту и открытые соединения. Windows, macOS, Linux; интерфейс на 8 языках; лицензия Apache-2.0.","tags":["локальный ИИ","десктоп"]},"CartaColibri":{"line":"Локальная ИИ-библиотека на движке Colibrì: индексирует выбранные вами папки, мгновенно ищет и просит локальную модель резюмировать, извлекать данные или синтезировать, всегда указывая исходный файл. Ничто не покидает ваш компьютер.","detail":"Программа на Rust с локальной страницей (127.0.0.1) и командной строкой. Индексирует выбранные вами папки (оригиналы только читаются, никогда не изменяются), ищет по полному тексту (слова, «фразы», префикс*, AND/OR/NOT, фильтры по типу, размеру, расположению) и группирует файлы. Локальная модель Colibrì делает резюме, извлекает данные (таблица или JSON, «НЕ НАЙДЕНО» вместо догадок), синтезирует или сравнивает, всегда с указанием источников [S1], [S2] и оценкой обоснованности. Также имеет небольшой браузер веб-захвата, MCP-сервер только для чтения, импорт (закладки, Obsidian, Zotero, RSS) и проверку вашего собственного текста по библиотеке. Без аккаунта, без телеметрии; интерфейс на 8 языках; альфа-версия 0.2; лицензия MIT.","tags":["локальный ИИ","библиотека"]},"PolyTabletop":{"line":"240 настольных игр против компьютера в терминале или графическом окне, а также игра вдвоём на одной клавиатуре или по сети. Написано на Rust; у движка и игр нет внешних зависимостей.","detail":"Clean-room коллекция настольных игр на Rust: 240 игр, в которые можно играть против компьютера, в терминале или в графическом окне, плюс игра за одним устройством и сетевая игра вдвоём. Абстрактная классика, карточные игры и игры в кости, оригинальные варианты современных механик под собственными названиями, кооперативные игры с ИИ-партнёром, игры со скрытыми ролями, party- и словесные игры; в каталоге 1200 записей, с набором инструментов для ролевых игр (кости, листы, генератор подземелий, симулятор сражений). ИИ-соперник (альфа-бета, MCTS), арена ИИ против ИИ, стенограммы и повторы. Интерфейс на 8 языках; версия 0.9; лицензия MIT или Apache-2.0.","tags":["настольные игры","Rust"]},"STRAJA":{"line":"Щит от ИИ-агентов, читающих ваш телефон: показывает, какие приложения могут читать ваши уведомления, экран, фотографии и SMS, предупреждает, когда новое получает доступ, и ведёт вас к настройкам, где можно отозвать разрешение. Без аккаунта, без разрешения INTERNET.","detail":"Приложение для Android (APK) и iPhone (неподписанный IPA). На Android перечисляет приложения с доступом к уведомлениям, службами специальных возможностей, ролью ассистента и разрешениями на медиа и SMS, с оценкой риска по каждому приложению и по телефону в целом; периодический монитор сравнивает телефон с базовым состоянием и уведомляет о каждом новом доступе. Открывает нужную страницу системных настроек для отзыва доступа и никогда ничего не меняет молча. Временный доступ с напоминанием и руководство по защите из 12 пунктов. На iPhone аудита нет (iOS скрывает разрешения других приложений), только руководство, ручной реестр и напоминания. Не может остановить агента. Без разрешения INTERNET, без резервного копирования; 8 языков; версия 1.0; лицензия MIT.","tags":["приватность","телефон"]},"CUPLAJ":{"line":"Телефония с общей линией для иммерсивного театра: флот обычных Android-телефонов превращается в частную АТС по Wi-Fi площадки; без облака, без аккаунтов, без рекламы. Фирменная функция — «cuplaj»: общая линия стационарных телефонов с 1980-х до примерно 2006 года.","detail":"Приложение для Android (APK) и для iPhone/iPad (неподписанный IPA). Организаторы и актёры общаются со зрителями по локальной сети Wi-Fi; один телефон (управляющий) служит коммутатором. Шесть телефонных эпох (1985 дисковый, 1995 кнопочный, 2003 мобильный, 2025 смартфон, 2045 носимые устройства, 2080 общий разум), спаренная линия, на которой два абонента делят одну линию, реальные звонки, оповещение по принципу «нажми и говори», закулисный канал, сигналы (полноэкранный текст, вибрация, звонок, вспышка, озвученный голос, призрачный звонок) и сценарий с GO и PLAY. Без инфраструктуры, необязательный сетевой ключ AES-128-GCM, прямые P2P-звонки. Без аналитики, без серверов, без аккаунтов. 8 языков; версия 1.10; лицензия MIT.","tags":["иммерсивный театр","телефония"]},"LUSTRUM":{"line":"Верните место на телефоне: находит ненужные файлы, дубликаты, похожие фотографии и остатки приложений и очищает их только с вашего согласия. Нет разрешения INTERNET, поэтому физически ничего никуда отправить не может.","detail":"Приложение для Android (Kotlin). Хранилище по типам файлов, большие, старые и ненужные файлы, точные дубликаты (размер, быстрый отпечаток, затем SHA-256), похожие фотографии (перцептивное хеширование), остатки удалённых приложений, сжатие JPEG, кэши, размытые и тёмные фотографии, Swiper (влево — удалить, вправо — оставить), очистка по расписанию и 30-дневная корзина LUSTRUM для отмены. Без разрешения INTERNET: ничего не покидает телефон. Никакой магии на уровне root: Android 11+ не пускает ни одно обычное приложение в папки данных других приложений. 8 языков (машинные переводы); бета-версия 0.8; лицензия MIT.","tags":["очистка телефона","Android"]},"STENOGRAMA":{"line":"Расшифровка длинного аудио прямо в браузере с локальным Whisper: один HTML-файл, без аккаунта, без сервера, без водяных знаков. Ваше аудио никогда не покидает устройство; скачивается только модель Whisper, один раз.","detail":"Читает MP3 и WAV частями (поэтому длина не ограничена памятью); другие форматы (M4A, OGG/Opus, MP4, FLAC) декодируются целиком. Каждый фрагмент нарезается по паузе, чтобы слова не разрывались; прогресс сохраняется, поэтому можно остановиться и продолжить. Встроенный в страницу редактор (щёлкните по времени, чтобы услышать место), удаление типичных «призрачных» фраз Whisper, экспорт в .txt, .srt, .vtt, .docx или в буфер обмена. Использует WebGPU, если доступно, иначе процессор (WASM). Устанавливаемое PWA; модель остаётся в кэше после первой загрузки. Библиотека загружается из jsDelivr при первой транскрипции, проверяется по SHA-384. Интерфейс на 7 языках; лицензия MIT.","tags":["расшифровка","аудио"]},"GERMEN":{"line":"Обучите небольшую языковую модель с нуля на чистом Rust на обычном процессоре: без Python, без CUDA, без аккаунта, без доступа к сети, без телеметрии. Один бинарный файл, один текстовый файл, одна команда.","detail":"Программа на Rust (на Burn, с его чисто-Rust CPU-бэкендом), которая обучает сеть типа GPT на байтах или на словаре BPE, выученном по вашему собственному тексту, а затем генерирует текст обученной моделью. GERMEN Studio: локальное окно (127.0.0.1) с кривой потерь, скоростью и образцами текста, на 8 языках. Команды для измерения скорости вашего компьютера и для проверки и починки файлов модели. Это мастерская для обучения и экспериментов, а не фабрика чат-ботов: модель на 1–25 миллионов параметров усваивает форму текста, а не знания о мире. Без GPU, без смешанной точности. Версия 0.6; лицензия MIT.","tags":["локальный ИИ","Rust"]},"CUANTOR":{"line":"Симулятор квантового компьютера для вашего рабочего стола, от 5 до 1000 кубитов, с интерфейсом в стиле IBM Quantum Composer. Точная математика, но не настоящее квантовое железо.","detail":"Программа на Rust из четырёх частей (ядро, окно, командная строка, связь с IBM) для Windows, macOS и Linux. Чертёжная доска как Composer от IBM: размещайте цветные вентили на линиях (кубитах) и наблюдайте, как столбцы и сфера показывают результат, пока текстовая панель вживую записывает ту же схему в OpenQASM и Qiskit. Три калькулятора: один, помнящий каждое число (до 28 кубитов), один очень быстрый для простых вентилей (до 4096) и один для схем с малым числом ветвлений. Измерение, сброс и if в середине выполнения, ваши собственные вентили, имитация шума, воспроизводимые результаты с зерном. Читает OpenQASM 2.0 и 3.0; схему можно открыть в IBM Composer или отправить на реальную машину IBM с вашим собственным ключом аккаунта (на реальном оборудовании IBM не проверено). Интерфейс на 8 языках; версия 0.2.","tags":["квантовый компьютер","симулятор"]}});
